PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=5000;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS bindings (user_id INTEGER PRIMARY KEY, tenant_key TEXT NOT NULL, app_id TEXT NOT NULL, open_id TEXT NOT NULL, display_name TEXT NOT NULL, version INTEGER NOT NULL, synced_at INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS binding_identity ON bindings(tenant_key,app_id,open_id) WHERE active=1;
CREATE TABLE IF NOT EXISTS preferences (user_id INTEGER PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, warning_micros INTEGER NOT NULL DEFAULT 5000000, critical_micros INTEGER NOT NULL DEFAULT 1000000, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS oauth_attempts (state_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, session_hash TEXT NOT NULL, browser_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, tenant_key TEXT NOT NULL DEFAULT '', app_id TEXT NOT NULL DEFAULT '', open_id TEXT NOT NULL DEFAULT '', display_name TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS alert_states (user_id INTEGER PRIMARY KEY, rule_version INTEGER NOT NULL, cycle INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 0, recovery_count INTEGER NOT NULL DEFAULT 0, last_sample_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS balance_snapshots (user_id INTEGER PRIMARY KEY, balance_micros INTEGER NOT NULL, currency TEXT NOT NULL, sampled_at INTEGER NOT NULL, active INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notification_outbox (event_id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, binding_version INTEGER NOT NULL, rule_version INTEGER NOT NULL, cycle INTEGER NOT NULL, level INTEGER NOT NULL, balance_micros INTEGER NOT NULL, threshold_micros INTEGER NOT NULL, sampled_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL, lease_until INTEGER NOT NULL DEFAULT 0, message_id TEXT NOT NULL DEFAULT '', last_error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(user_id,binding_version,rule_version,cycle,level));
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, action TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS metrics (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_preferences (user_id INTEGER PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, warning_percent INTEGER NOT NULL DEFAULT 80, critical_percent INTEGER NOT NULL DEFAULT 95, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscription_snapshots (user_id INTEGER PRIMARY KEY, sampled_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_states (user_id INTEGER NOT NULL, subscription_id INTEGER NOT NULL, kind TEXT NOT NULL, window_start TEXT NOT NULL, limit_micros INTEGER NOT NULL, binding_version INTEGER NOT NULL, rule_version INTEGER NOT NULL, cycle INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,subscription_id,kind));
CREATE TABLE IF NOT EXISTS subscription_outbox (event_id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, subscription_id INTEGER NOT NULL, kind TEXT NOT NULL, window_start TEXT NOT NULL, limit_micros INTEGER NOT NULL, binding_version INTEGER NOT NULL, rule_version INTEGER NOT NULL, cycle INTEGER NOT NULL, level INTEGER NOT NULL, sampled_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL, lease_until INTEGER NOT NULL DEFAULT 0, message_id TEXT NOT NULL DEFAULT '', last_error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(user_id,subscription_id,kind,window_start,binding_version,rule_version,cycle,level));
CREATE INDEX IF NOT EXISTS subscription_pending ON subscription_outbox(status,next_at);
PRAGMA user_version=2;
